#!/usr/bin/env bash
# Lightek existing-Ubuntu website deployment. Run from the Rails checkout.
set -euo pipefail
umask 077
command -v python3 >/dev/null || { echo 'Python 3 is required.'; exit 1; }
TASK_RUNNER=$(mktemp "${TMPDIR:-/tmp}/lightek-website-runner.XXXXXXXX")
trap 'rm -f "$TASK_RUNNER"' EXIT
cat > "$TASK_RUNNER" <<'LIGHTEK_PYTHON'
import argparse,base64,contextlib,datetime,getpass,hashlib,http.cookiejar,ipaddress,json,os,pathlib,re,secrets,shlex,shutil,socket,subprocess,sys,tarfile,tempfile,time,urllib.error,urllib.parse,urllib.request
from html.parser import HTMLParser
