class DeployError(Exception): pass

def run(args, **kwargs):
    result = subprocess.run(args, check=False, **kwargs)
    if result.returncode: raise DeployError('Command failed ('+str(result.returncode)+'): '+shlex.join(args[:3]))
    return result

def prompt(value,label,default=None):
    if value: return value
    answer=input(label+(' ['+default+']' if default else '')+': ').strip()
    if not answer: answer=default
    if not answer: raise DeployError(label+' is required')
    return answer

def normalize_ssh(value, explicit_port=None):
    try: parts=shlex.split(value.strip())
    except ValueError: raise DeployError('SSH destination has unmatched quotes')
    if parts and parts[0] in ('ssh','/usr/bin/ssh'): parts=parts[1:]
    command_port=None
    if parts and parts[0]=='-p':
        if len(parts)<3:raise DeployError('Use ssh -p PORT user@host')
        command_port=parts[1];parts=parts[2:]
    elif parts and parts[0].startswith('-p') and len(parts[0])>2:
        command_port=parts[0][2:];parts=parts[1:]
    if len(parts)!=1 or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.@:-]*',parts[0]) or parts[0].count('@')>1:
        raise DeployError('Enter user@host, an SSH alias, or ssh [-p PORT] user@host; do not include a remote command')
    if '@' in parts[0] and not all(parts[0].split('@')):raise DeployError('Both SSH username and host are required')
    try:
        port=int(explicit_port if explicit_port is not None else (command_port or 22))
        if command_port is not None and explicit_port is not None and int(command_port)!=port:raise DeployError('Conflicting SSH ports')
    except ValueError:raise DeployError('SSH port must be a number')
    if not 0<port<65536:raise DeployError('Invalid SSH port')
    return parts[0],port

def validate(c, require_password=True):
    labels=c['domain'].split('.')
    if len(labels)<2 or len(c['domain'])>253 or any(not re.fullmatch(r'[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?',x) for x in labels):raise DeployError('Use a valid DNS hostname')
    if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.@:-]*',c['ssh']) or c['ssh'].count('@')>1:raise DeployError('Use an SSH alias or user@host')
    if not 0<int(c['port'])<65536:raise DeployError('Invalid SSH port')
    if not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+',c['email']):raise DeployError('Invalid email')
    if not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+',c['owner_email']):raise DeployError('Invalid owner email')
    if require_password and len(c['owner_password'])<8:raise DeployError('Owner password must have at least 8 characters')
    for field in ('site_name','headline','description'):
        if not c[field].strip() or len(c[field])>3000:raise DeployError('Invalid '+field)

EXCLUDED={'.git','.bundle','.ssh','storage','tmp','log','node_modules','coverage','test','spec','uploads'}
def ignored(directory,names):
    blocked = {'bundle','cache'} if pathlib.Path(directory).name == 'vendor' else ({'assets'} if pathlib.Path(directory).name == 'public' else set())
    if pathlib.Path(directory).name == 'config': blocked.add('credentials.yml.enc')
    if pathlib.Path(directory).name == 'credentials': blocked.update(n for n in names if n.endswith('.yml.enc'))
    return [n for n in names if n in blocked or n in EXCLUDED or n.startswith('.') or n.endswith(('.key','.pem','.p12','.pfx','.log','.bundle','.so','.zip','.mov')) or '.bak' in n]

def copy_source(source,destination):
    # Symlinks could package files outside this checkout. Require actual source
    # directories for deployment rather than silently following secret paths.
    for parent,dirs,files in os.walk(source,followlinks=False):
        blocked=set(ignored(parent,dirs+files)); dirs[:]=[d for d in dirs if d not in blocked]
        for name in dirs+files:
            if name not in blocked and (pathlib.Path(parent)/name).is_symlink():raise DeployError('Source contains a symlink; resolve it before packaging: '+str(pathlib.Path(parent)/name))
    shutil.copytree(source,destination,ignore=ignored,dirs_exist_ok=True)

def ruby_string(v): return json.dumps(str(v),ensure_ascii=True)

def make_gemfile(meta,app):
    lines=['source "https://rubygems.org"']
    for gem in sorted(meta['gems'],key=lambda x:x['name']):
        name=gem['name']
        if name=='bundler':continue
        if not re.fullmatch(r'[A-Za-z0-9_-]+',name):raise DeployError('Invalid gem name')
        options=[]
        if gem.get('path'):
            dest=app/'vendor'/'lightek_sources'/name
            copy_source(pathlib.Path(gem['path']),dest)
            for spec in dest.glob('*.gemspec'): spec.unlink()
            (dest/(name+'.gemspec')).write_text(gem['gemspec'])
            options.append('path: '+ruby_string('vendor/lightek_sources/'+name))
        auto=gem.get('autorequire')
        if auto==[]: options.append('require: false')
        elif auto is not None: options.append('require: '+json.dumps(auto))
        lines.append('gem '+ruby_string(name)+', '+ruby_string('='+gem['version'])+(', '+', '.join(options) if options else ''))
    (app/'Gemfile').write_text('\n'.join(lines)+'\n')
    (app/'Gemfile.lock').unlink(missing_ok=True)

def add_routes(text):
    marker='Rails.application.routes.draw do'
    if text.count(marker)!=1:raise DeployError('Cannot safely locate Rails routes block')
    return text.replace(marker,marker+'''
  # Lightek website deployment: active only in the isolated deployed instance.
  if ENV["LIGHTEK_DEPLOYED_SITE_HOST"].present?
    get "/", to: "lightek_website_delivery#show"
    get "/__lightek/website-health", to: "lightek_website_delivery#health"
    get "/site/:slug", to: "lightek_website_delivery#show", constraints: {slug: /[a-zA-Z0-9_-]+/}
  end
''',1)

def add_boot_sync_hook(text):
    hook='require_relative "../lib/lightek/dashboard_boot_sync"'
    if hook in text:return text
    pattern=r'''(?m)^require_relative ["']boot["'][ \t]*$'''
    if len(re.findall(pattern,text))!=1:raise DeployError('Cannot locate config/application.rb boot require')
    return re.sub(pattern,lambda match:match.group(0)+'\n'+hook,text,count=1)

def extra_env(path,root):
    data={}
    if path:
        for line in pathlib.Path(path).read_text().splitlines():
            line=line.strip()
            if not line or line.startswith('#'):continue
            if '=' not in line:raise DeployError('Environment file must use KEY=value lines')
            key,val=line.split('=',1)
            if not re.fullmatch(r'[A-Z][A-Z0-9_]*',key):raise DeployError('Invalid environment key')
            if val[:1] in ('"',"'"):
                if len(val)<2 or val[-1]!=val[0]:raise DeployError('Invalid quoted environment value')
                val=val[1:-1]
            if any(x in val for x in '\r\n\x00$'):raise DeployError('Multiline or interpolated environment values are unsupported')
            if key in {'DATABASE_URL','POSTGRES_USER','POSTGRES_PASSWORD','POSTGRES_DB','DB_HOST','REDIS_URL','RAILS_ENV','RACK_ENV','APP_HOST','LIGHTEK_RELEASE','LIGHTEK_DEPLOYED_SITE_HOST','APP_PORT','PROJECT'}:raise DeployError('Infrastructure variable cannot override the isolated deployment: '+key)
            data[key]=val
    return data

