def rails_code(root,stage,code,data):
    path=stage/('runner-'+secrets.token_hex(4)+'.rb');path.write_text(code)
    env=dict(os.environ,RAILS_ENV=os.environ.get('RAILS_ENV','development'))
    p=subprocess.run(['bin/rails','runner',str(path)],cwd=root,env=env,input=json.dumps(data),text=True,capture_output=True)
    if p.returncode:raise DeployError('Rails integration failed: '+p.stderr[-2000:]+p.stdout[-1000:])
    return p.stdout

def dns_setup(root,stage,c):
    host=c['ssh'].split('@')[-1]
    default=None
    try:
        ips=list(dict.fromkeys(x[4][0] for x in socket.getaddrinfo(host,None)))
        default=next((x for x in ips if ipaddress.ip_address(x).is_global),None)
    except socket.gaierror:pass
    ip=c.get('public_ip') or prompt(None,'Public server IP for this hostname',default)
    try:
        address=ipaddress.ip_address(ip)
        if not address.is_global:raise DeployError('A public IP is required for the public HTTPS deployment')
        ip=str(address)
    except ValueError:raise DeployError('Enter a public IPv4 or IPv6 address')
    try:
        published={x[4][0] for x in socket.getaddrinfo(c['domain'],None)}
    except socket.gaierror:published=set()
    if published=={ip}:
        print('DNS: matched',flush=True)
        return
    result=rails_code(root,stage,DNS_CODE,dict(domain=c['domain'],ip=ip))
    line=next((x for x in result.splitlines() if x.startswith('LIGHTEK_DNS_RESULT=')),None)
    if not line:raise DeployError('DNS integration returned no result')
    status=json.loads(line.split('=',1)[1])
    if status['status']=='not_configured':
        if c.get('_headless'):raise DeployError('Website DNS is not published: create an A/AAAA record for '+c['domain']+' pointing to '+ip+' at the domain\'s authoritative DNS provider, then retry. GoDaddy is optional.')
        print('No managed DNS credentials for this zone. Set '+c['domain']+' to '+ip+' at its authoritative DNS provider, then press Enter.')
        input()
    else:print('DNS: '+status['status'])
    # Check every currently published address; an old AAAA can break ACME even
    # when the A record is correct. Propagation is never claimed from a write.
    for attempt in range(12):
        try: resolved={x[4][0] for x in socket.getaddrinfo(c['domain'],None)}
        except socket.gaierror:resolved=set()
        if resolved=={ip}:return
        if attempt<11:
            print('Waiting for DNS; observed '+(', '.join(sorted(resolved)) or 'no address'),flush=True)
            time.sleep(10)
    raise DeployError('DNS has not converged to '+ip+'. Rerun after propagation; no server deployment started.')

class TokenParser(HTMLParser):
    def __init__(self):super().__init__();self.token=None
    def handle_starttag(self,tag,attrs):
        d=dict(attrs)
        if tag=='input' and d.get('name')=='authenticity_token':self.token=d.get('value')

def verify_public(c):
    base='https://'+c['domain']
    opener=urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))
    def request(path,data=None):
        req=urllib.request.Request(base+path,data=data,headers={'User-Agent':'Mozilla/5.0 (X11; Linux x86_64; rv:155.0) Gecko/20100101 Firefox/155.0','Accept':'text/html,application/json'})
        with opener.open(req,timeout=30) as r:return r.geturl(),r.read().decode(),r.status
    _,body,_=request('/__lightek/website-health');h=json.loads(body)
    if h.get('release')!=c['release'] or h.get('domain')!=c['domain'] or h.get('sections',0)<3:raise DeployError('Public website health does not match this release')
    _,html,_=request('/')
    if 'name="lightek-release" content="'+c['release']+'"' not in html:raise DeployError('Public homepage is not this deployed template')
    _,login,_=request('/session/new');parser=TokenParser();parser.feed(login)
    if not parser.token:raise DeployError('Sign-in form has no CSRF token')
    data=urllib.parse.urlencode(dict(authenticity_token=parser.token,email_address=c['owner_email'],password=c['owner_password'])).encode()
    request('/session',data)
    final,body,status=request('/dashboard/pages')
    if status!=200 or urllib.parse.urlparse(final).path.startswith('/session'):raise DeployError('Owner cannot open website management after sign-in')
    # Website acceptance alone is not sufficient for a paid full-application
    # installation. Probe other mounted Lightek dashboards using the same
    # authenticated session and reject redirects to sign-in.
    checks=('/dashboard/business','/dashboard/settings',
            '/dashboard/commerce/orders?site_id='+str(h['site_id']))
    for path in checks:
        final,body,status=request(path)
        dest=urllib.parse.urlparse(final).path
        expected=urllib.parse.urlparse(path).path
        if status!=200 or dest.rstrip('/')!=expected:
            raise DeployError('Full Lightek dashboard acceptance failed: '+path)
    h['full_application_dashboard_verified']=True
    return h

@contextlib.contextmanager
def authenticated_ssh(config):
    # Keep the socket path short for macOS's Unix-domain socket length limit.
    with tempfile.TemporaryDirectory(prefix='lt-ssh-',dir='/tmp') as directory:
        os.chmod(directory,0o700)
        base=['ssh','-o','ConnectTimeout=20','-o','ServerAliveInterval=30',
              '-o','ServerAliveCountMax=3','-o','ControlPath='+directory+'/c',
              '-p',str(config['port'])]
        destination=config['ssh']
        if config.get('ssh_key_path'):
            base += ['-i',config['ssh_key_path'],'-o','IdentitiesOnly=yes']
        if config.get('_headless'):
            base += ['-o','BatchMode=yes','-o','StrictHostKeyChecking=accept-new']
        try:
            print("Connecting to the server. Use its SSH password; the website-owner password is separate.",flush=True)
            run(base+['-M','-N','-f','-o','ControlMaster=yes','-o','ControlPersist=600',destination])
            # Reuse authentication for every transfer, installer and cleanup.
            # If the master connection is lost, fail without password loops.
            yield base+['-o','ControlMaster=no','-o','BatchMode=yes',destination]
        finally:
            try:
                subprocess.run(base+['-o','BatchMode=yes','-O','exit',destination],
                    stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=10)
            except (OSError,subprocess.TimeoutExpired):pass

def main():
    parser=argparse.ArgumentParser(description='Deploy the current Lightek checkout to an existing Ubuntu server.')
    for name in ('ssh','domain','email','name','headline','description','env-file'):parser.add_argument('--'+name)
    parser.add_argument('--ssh-port',type=int)
    parser.add_argument('--owner-role',choices=['admin','super_admin'],default='admin')
    parser.add_argument('--config-stdin',action='store_true')
    args=parser.parse_args();print('LIGHTEK_WEBSITE_DEPLOYER=1.1.1',flush=True);root=pathlib.Path.cwd().resolve()
    if not all((root/p).is_file() for p in ['Gemfile','bin/rails','config/routes.rb']):raise DeployError('Run from the lightekmcg-site checkout')
    if args.config_stdin:
        c=json.load(sys.stdin)
        c['_headless']=True
        c['ssh'],c['port']=normalize_ssh(c['ssh'],c.get('port'))
        c['extra_env']={}
        if not c.get('public_ip') or not c.get('ssh_key_path'):raise DeployError('Application deployment requires public_ip and ssh_key_path')
    else:
        destination,port=normalize_ssh(prompt(args.ssh,'SSH destination (user@host, SSH alias, or ssh user@host)'),args.ssh_port)
        c=dict(ssh=destination,port=port,
            domain=prompt(args.domain,'Website hostname (full domain, e.g. octavia.lightekmcg.com)').lower(),email=prompt(args.email,'Certificate contact email'),
            site_name=prompt(args.name,'Website/business name'),headline=prompt(args.headline,'Homepage headline'),
            description=prompt(args.description,'Short website description'),owner_role=args.owner_role)
        c['owner_email']=prompt(None,'Website owner sign-in email',c['email'])
        validate(c,require_password=False)
        c['owner_password']=getpass.getpass('Owner password (8+ characters; never printed): ')
        if c['owner_password']!=getpass.getpass('Confirm owner password: '):raise DeployError('Passwords differ')
        c['extra_env']=extra_env(args.env_file,root)
    if c.get('owner_role','admin') not in ('admin','super_admin'):raise DeployError('Invalid owner role')
    validate(c);c['release']=secrets.token_hex(10)
    os.umask(0o077)
    with authenticated_ssh(c) as ssh:
        run(ssh+['test -f /etc/os-release && . /etc/os-release && [ "$ID" = ubuntu ] && printf "SSH_UBUNTU_OK\\n"'])
        with tempfile.TemporaryDirectory(prefix='lightek-deploy-') as temp:
            stage=pathlib.Path(temp)
            for name,encoded in PAYLOAD.items():
                p=stage/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(encoded))
            print('Packaging the local Rails application and private gem sources...',flush=True)
            metadata=stage/'metadata.json'
            run(['bundle','exec','ruby',str(stage/'metadata.rb'),str(metadata)],cwd=root)
            meta=json.loads(metadata.read_text())
            c['bundler']=meta['bundler']
            if not re.fullmatch(r'[0-9]+(?:\.[0-9A-Za-z]+)+',c['bundler']):raise DeployError('Invalid Bundler version in package metadata')
            if meta['ruby']!='3.3.6':raise DeployError('This deployment matches Ruby 3.3.6; current Ruby is '+meta['ruby'])
            app=stage/'app';app.mkdir()
            for name in ['app','bin','config','db','lib','public','script','vendor']:
                if (root/name).is_dir():copy_source(root/name,app/name)
            for name in ['Rakefile','config.ru','Gemfile.lock','package.json','yarn.lock']:
                if (root/name).is_file():shutil.copy2(root/name,app/name)
            for p in (stage/'payload').rglob('*'):
                if p.is_file():
                    dest=app/p.relative_to(stage/'payload');dest.parent.mkdir(parents=True,exist_ok=True)
                    if dest.exists():
                        if dest.read_bytes()==p.read_bytes():continue
                        raise DeployError('Deployment helper already exists with different contents: '+str(dest.relative_to(app)))
                    shutil.copy2(p,dest)
            route=app/'config/routes.rb';route.write_text(add_routes(route.read_text()))
            application=app/'config/application.rb';application.write_text(add_boot_sync_hook(application.read_text()))
            make_gemfile(meta,app)
            if not c.get('sidebar_sections'):
                nav=rails_code(root,stage,'require "json"; puts "LIGHTEK_SIDEBAR="+JSON.generate(DymondDash::NavSection.order(:position).map { |s| s.attributes.slice("slug","label","position") })',{})
                line=next((x for x in nav.splitlines() if x.startswith('LIGHTEK_SIDEBAR=')),None)
                if not line:raise DeployError('Sidebar configuration was not returned')
                c['sidebar_sections']=json.loads(line.split('=',1)[1])
            shutil.copy2(stage/'Dockerfile',app/'Dockerfile')
            (app/'.dockerignore').write_text('.env*\ndeployment.env\nconfig/master.key\nconfig/credentials/*.key\n.git\nlog\ntmp\nstorage\n')
            entry=app/'bin/lightek-container-entrypoint';entry.write_text('#!/bin/sh\nset -eu\nrm -f /app/tmp/pids/server.pid\nexec "$@"\n');entry.chmod(0o755)
            for p in (app/'bin').iterdir():
                if p.is_file():p.chmod(p.stat().st_mode|0o111)
            (stage/'settings.json').write_text(json.dumps(c))
            syntax_files=list((app/'app').rglob('*.rb'))+[app/'config/routes.rb',app/'config/application.rb']
            syntax_manifest=stage/'ruby-syntax.json';syntax_manifest.write_text(json.dumps([str(p) for p in syntax_files]))
            run(['ruby','-rjson','-e','JSON.parse(File.read(ARGV.fetch(0))).each { |path| RubyVM::InstructionSequence.compile_file(path) }',str(syntax_manifest)])
            print('Checking hostname DNS...',flush=True)
            dns_setup(root,stage,c)
            p=run(ssh+['umask 077; mktemp -d /tmp/lightek-upload.XXXXXXXX'],text=True,capture_output=True)
            remote=p.stdout.strip()
            if not re.fullmatch(r'/tmp/lightek-upload\.[A-Za-z0-9]+',remote):raise DeployError('Invalid remote staging path')
            package=stage/'release.tgz'
            with tarfile.open(package,'w:gz') as tar:
                for name in ['app','settings.json','compose.yml','remote.sh']:tar.add(stage/name,arcname=name)
            try:
                print('Uploading release using the authenticated connection...',flush=True)
                with package.open('rb') as stream:run(ssh+['cat > '+remote+'/release.tgz'],stdin=stream)
                run(ssh+['tar -xzf '+remote+'/release.tgz -C '+remote+' && chmod 700 '+remote+'/remote.sh'])
                print('Installing on the server. A sudo prompt, if shown, is for the Linux account.',flush=True)
                run(ssh[:1]+['-tt']+ssh[1:]+['sudo bash '+remote+'/remote.sh'])
                # The existing Lightek Mail installer is private/held by design.
                # Explicitly opt in only on a dedicated Ubuntu 24.04 customer VPS.
                # SMTP delivery is not enabled by this step.
                if c.get('_headless') or os.environ.get('LIGHTEK_INSTALL_PRIVATE_MAIL_NODE')=='true':
                    mail_script='/opt/lightek-sites/'+c['domain']+'/releases/'+c['release']+'/lib/scripts/setup_lightek_mail_node.sh'
                    check='systemctl is-active --quiet postfix && systemctl is-active --quiet rspamd && systemctl is-active --quiet lightek-mail-redis'
                    command='if '+check+'; then echo LIGHTEK_MAIL_PRIVATE_NODE_READY; else sudo LIGHTEK_MAIL_HOST='+shlex.quote('mail.'+c['domain'])+' LIGHTEK_MAIL_DKIM_DOMAIN='+shlex.quote(c['domain'])+' bash '+shlex.quote(mail_script)+' --install; fi'
                    run(ssh+[command])
                health=verify_public(c)
                # Mail egress/ingress restrictions are controlled by the VPS
                # provider. A configured instance may activate while external
                # mail delivery is pending the provider's port-unblock ticket.
                if not c.get('_headless'):
                    config_result=run(ssh+['printf "%s" "${USER:-root}"'],capture_output=True,text=True)
                    user=c['ssh'].split('@')[0] if '@' in c['ssh'] else config_result.stdout.strip()
                    result=rails_code(root,stage,REGISTER_CODE,dict(domain=c['domain'],ssh_host=c['ssh'].split('@')[-1],ssh_user=user,port=c['port'],release=c['release']))
                    print('\n'.join(x for x in result.splitlines() if x.startswith('GATEKEEPER_NODE_REGISTERED=')))
                receipt=root/'tmp/website_deploy'/('receipt-'+c['release']+'.json');receipt.parent.mkdir(parents=True,exist_ok=True)
                receipt.write_text(json.dumps(dict(package_sha256=hashlib.sha256(package.read_bytes()).hexdigest(),url='https://'+c['domain'],release=c['release'],public_https_verified=True,owner_login_verified=True,health=health,verified_at=datetime.datetime.now(datetime.timezone.utc).isoformat()),indent=2))
                print('WEBSITE_DEPLOYMENT_PASS=https://'+c['domain'])
                print('Owner management: https://'+c['domain']+'/dashboard/pages')
                print('Receipt: '+str(receipt))
            finally:
                with contextlib.suppress(OSError,subprocess.TimeoutExpired):
                    subprocess.run(ssh+['rm -rf -- '+remote],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=20)

if __name__=='__main__':
    try:main()
    except (DeployError,KeyboardInterrupt,urllib.error.URLError) as e:
        print('\nDEPLOYMENT_STOPPED: '+str(e),file=sys.stderr)
        sys.exit(1)

